import {addedPhoto} from './photos.mjs';
export async function samplePhotos(){const photos=[];for(let i=0;i<2;i++){const canvas=document.createElement('canvas');canvas.width=900;canvas.height=600;const ctx=canvas.getContext('2d');ctx.fillStyle='#edf3fa';ctx.fillRect(0,0,900,600);ctx.fillStyle='#003d7c';ctx.font='bold 30px Arial';ctx.fillText('FICTIONAL TRAINING ILLUSTRATION',34,52);ctx.font='22px Arial';ctx.fillText(i?'Example 2: walkway cleared':'Example 1: boxes in walkway',34,94);ctx.fillStyle='#fff';ctx.fillRect(230,135,440,330);ctx.strokeStyle='#ef7c00';ctx.lineWidth=8;ctx.setLineDash([18,12]);ctx.strokeRect(230,135,440,330);ctx.setLineDash([]);if(!i){ctx.fillStyle='#c89362';ctx.fillRect(320,240,160,130);ctx.fillRect(450,320,130,110);}ctx.fillStyle='#003d7c';ctx.font='bold 24px Arial';ctx.fillText('DESIGNATED WALKWAY',280,180);ctx.font='20px Arial';ctx.fillText('Sample only - not inspection evidence',34,550);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Sample image could not be created.');const photo=addedPhoto({name:'fictional-example-'+(i+1)+'.png'},blob,photos,null,'sample-photo-'+i);photo.caption='Fictional illustration: '+(i?'walkway clear':'boxes obstructing walkway');photos.push(photo);}return photos;}
